import java.util.*;

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine();
        char[] arr = line.toCharArray();
        int len = arr.length;
        if (len == 1) {
            if (arr[0] == '0' || arr[0] == '_' || arr[0] == 'X') {
                System.out.println(1);
            } else {
                System.out.println(0);
            }
            return;
        }
        if (arr[0] == '0') {
            System.out.println(0);
            return;
        }
        boolean hasX = false;
        for (char c : arr) {
            if (c == 'X') {
                hasX = true;
                break;
            }
        }
        long totalCount = 0;
        if (hasX) {
            for (int digit = 0; digit <= 9; digit++) {
                char[] tempArr = Arrays.copyOf(arr, len);
                if (tempArr[0] == 'X' && digit == 0) continue;
                for (int i = 0; i < len; i++) {
                    if (tempArr[i] == 'X') {
                        tempArr[i] = (char) (digit + '0');
                    }
                }
                long backVal = back(tempArr);
                long pre = 1;
                for (int j = 0; j < len - 2; j++) {
                    if (tempArr[j] == '_') {
                        pre *= (j == 0) ? 9 : 10;
                    }
                }
                totalCount += pre * backVal;
            }
        } else {
            long backVal = back(arr);
            long pre = 1;
            for (int j = 0; j < len - 2; j++) {
                if (arr[j] == '_') {
                    pre *= (j == 0) ? 9 : 10;
                }
            }
            totalCount += pre * backVal;
        }
        System.out.println(totalCount);
    }

    static long back(char[] arr) {
        int n = arr.length;
        if (fnc(arr, n - 1) && fnc(arr, n - 2)) {
            long num = Long.parseLong("" + arr[n - 2] + arr[n - 1]);
            if (num % 25 == 0) {
                if (num == 0) return 1;
                return 1;
            } else {
                return 0;
            }
        } else if (arr[n - 1] == '_' && arr[n - 2] == '_') {
            return 4;
        } else if (arr[n - 1] == '_') {
            if (arr[n - 2] == '2' || arr[n - 2] == '0' || arr[n - 2] == '7' || arr[n - 2] == '5') {
                if (arr[n - 2] == '0') return 1;
                return 1;
            } else {
                return 0;
            }
        } else {
            if (arr[n - 1] == '0' || arr[n - 1] == '5') {
                if (arr[n - 1] == '0') return 1;
                return 1;
            } else {
                return 0;
            }
        }
    }

    static boolean fnc(char[] arr, int i) {
        return arr[i] != '_';
    }
}
